"""Authored content for the remaining course; no PPT or runtime side effects."""
from pathlib import Path
import json
from write_phase1 import slide, agenda, write_lesson, UI, LAYOUT, LEARN

ROOT = Path(__file__).resolve().parent

def component(name, kind, role):
    return dict(name=name, type=kind, role=role)

def task(title, steps, question, answer):
    return dict(title=title, steps=steps, question=question, answer=answer)

def test(action, expected):
    return dict(action=action, expected=expected)

def question(q, a):
    return dict(q=q, a=a)

def source(title, url, use):
    return dict(title=title, url=url, use=use)

def base(n, title, work, goals, summary, scope, components, tasks, tests, pitfalls, challenges, exits, schedule, slides, sources):
    spec = json.loads((ROOT.parent/'aia'/f'lesson{n:02}'/'artifact-spec.json').read_text(encoding='utf8'))
    name = spec['projectName']
    logic=[]
    for row in spec['tests']:
        if 'event' in row and 'expect' in row:
            logic.append(dict(event=row['event'], actions=[k+' ← '+str(v) for k,v in row['expect'].items()]))
    kept='、'.join(spec.get('classroomKept', []))
    return dict(lesson=n,title=title,projectName=name,exampleTitle=work,durationMinutes=90,
                goals=goals,exampleSpec=dict(summary=summary,scope=scope,components=components,logic=logic),
                versions={'answer':name+'.aia：完整参考答案，含本课全部交互。',
                          'class':name+'Class.aia：保留'+kept+'；'+'；'.join(spec.get('classroomTasks',[]))+'。',
                          'starter':name+'Starter.aia：组件、初始属性与素材齐全，没有积木。'},
                agenda=agenda(schedule),tasks=tasks,tests=tests,misconceptions=pitfalls,
                challenges=[dict(level=level,task=text) for level,text in zip(['基础','提高','拓展'],challenges)],
                exitQuestions=exits,sources=sources,slides=slides,
                componentMetadata={c['type']:c['version'] for c in spec['components']})

