    tests=[test('固定答案12，依次提交8、16、12','偏小、偏大、猜中；有效次数1、2、3。'),test('新一局提交0、21、2.5、空白','提示请输入1～20的整数，次数不增加。'),test('猜中后再次提交','保持成功结果与次数。'),test('换一局后提交合法整数','次数从0重新累计，结束状态已清除。'),test('恢复随机后多次换一局','答案始终在1～20，允许与上次相同；不在每次猜测时重选答案。')],
    blocks=[('一局共用一个秘密答案',['新一局随机1～20','次数归0，已结束为假','两个入口复用同一过程'],'过程名实际为新一局，不是蓝图早期的新一轮。Class版已完整提供，学生先追踪状态初始化。'),('检查猜测的有效分支',['合法后才计次','按偏小、偏大、相等给提示','猜中时设置已结束'],'教师展示时只读偏小、偏大、猜中三个区域，不要求一次看清整个长过程。三种反馈中的比较对象始终是同一局的答案。'),('换一局的共同入口',['NewButton.Click调用新一局','不要只清屏幕文字','数据和显示一起恢复'],'把入口与过程定义区分开。按钮显示文字换一局，组件内部名仍是NewButton。')],
