    tests=[test('输入3生成','九行：3×1=3至3×9=27；总和135。'),test('连续生成3两次','第二次仍九行、总和135，不翻倍。'),test('生成3后改为1生成','九行1的算式，总和45，不残留3的文字。'),test('输入0、10、2.5或空白','提示请输入1～9的整数。')],
