    trace=[['行3的轮次','本轮乘积','执行后总和'],['i=1','3','3'],['i=2','6','9'],['i=3','9','18'],['i=9','27','135']],
    pitfalls=[['屏幕只剩最后一行','追加时没有连接旧输出。'],['连续生成后18行','循环前未清输出。'],['第二次总和270','循环前没有清零。'],['总和只有27','把清零放进循环体，每轮覆盖前面结果。']],
    challenges=['生成九行算式和正确总和，重复生成不累加旧结果。','把循环终点改为12，先预测行3总和234，再测试并同步范围说明。','增加步长为2的奇数乘法练习，先列出会执行哪些i，再决定界面说明。'],
    exits=[question('行是3，i从1到9，循环执行几次？','9次；行3是每轮乘数，不决定循环次数。'),question('输出←当前算式和输出←旧输出+当前算式有何区别？','前者覆盖，后者追加并保留旧行。'),question('清零、累加、显示分别应放哪里？','清零在循环前，累加在循环内，完整显示在循环后。')],
