    tasks=[task('读懂等待的截止时刻',['导入Class版，查看Clock1.TimerInterval为20，初始不启用。','读开始等待：状态等待，截止=SystemTime+随机1000～3000，启用Clock。','画出准备→等待→可点→结束的时间线。'],'等待两秒应阻塞程序一直不响应吗？','不应。本工程用截止时刻与Timer检查，让界面仍能处理抢跑点击；没有阻塞睡眠。'),task('添加信号出现的事件',['添加Clock1.Timer，只在状态为等待且SystemTime≥截止时处理。','设置状态为可点，记录开始时刻=SystemTime，并更新颜色及“现在点”文字。','停止Clock计时，防止重复重写开始时刻。'],'为什么变绿后要停止Timer或阻止重复记录？','重复改写开始时刻会让反应差值接近0，起点应是一次实际信号出现。'),task('按状态处理响应按钮',['添加ReactButton.Click：等待则停止Clock、提示抢跑、状态结束。','可点则显示SystemTime-开始时刻并结束；结束状态保持成绩。','测试抢跑与正常响应，再点击开始重玩。'],'结束后反复点击为什么不能覆盖成绩？','该局已经完成，重复点击不属于新的有效测试；需要状态保护，开始按钮才开启下一局。')],
    tests=[test('开始后立即点击响应','抢跑提示，状态结束，Clock停止。'),test('等待信号文字出现后约半秒点击','得到约500ms量级结果，允许界面、触摸与调度误差。'),test('结束后反复点击响应','结果保持不变。'),test('一轮结束后再次开始','旧结果恢复等待提示，重新进入随机等待。'),test('信号出现后观察Clock','已停止，开始时刻不再反复改写。')],
    blocks=[('随机等待的准备',['截止=当前时刻+随机时长','状态切到等待','Clock开始检查'],'Class版完整提供。讲清随机值是1000到3000毫秒，不是1000到3000次Timer；1秒=1000毫秒。'),('截止后记录信号时刻',['等待且到达截止才处理','只记录一次开始时刻','文字与颜色一起给信号'],'实际变量名是开始时刻，不是早期蓝图中的变绿时刻。结束Timer检查不影响之后按钮读取SystemTime。'),('点击由状态选择结果',['等待：抢跑并结束','可点：计算时刻差并结束','结束：保持结果'],'完整答案截图对应ReactButton.Click。准备状态可提示先开始，结束状态不覆盖成绩；注意两者不要合并为统一提示。')],
    trace=[['当时状态','事件','结果'],['准备','点击开始','等待，设未来截止'],['等待','提前点响应','抢跑，结束'],['等待','Timer达到截止','可点，记开始时刻'],['可点','点响应','显示时刻差，结束'],['结束','再点响应','保持成绩']],
    pitfalls=[['结果几乎总是0','开始时刻可能被每次Timer重复更新。'],['抢跑也获得成绩','ReactButton没有区分等待和可点。'],['时间是负数','检查差值方向及两个时刻是否都在同一轮记录。'],['只用绿色通知用户','同时给出“现在点”文字，不能只靠颜色。']],
    challenges=['完成信号与响应事件，抢跑、正常与结束三类行为清楚。','把成绩说明改成友好反馈，保留毫秒数和误差说明。','增加最佳成绩状态，先规定抢跑不参与比较，再设计重置最佳值入口。'],
    exits=[question('1000ms出现信号，1520ms点击，成绩怎么算？','1520-1000=520毫秒。'),question('20ms的Timer间隔等于成绩误差一定小于20ms吗？','不等于；还存在Timer调度、界面绘制与触摸处理误差。'),question('为什么抢跑和结束后点击需要不同处理？','抢跑要终止本轮并提示；结束后只保持已有成绩，不把重复点击当新成绩。')],
