    transfer=['第19课接住加分，漏接重新出现','这次漏接有代价，分数影响难度','保留基本玩法，只扩展明确的新规则'],
    states=[['得分','初始0'],['生命','初始3，漏接扣1'],['状态','待开始、运行、暂停、结束'],['下落步长','初始5，每5分+1，上限12']],
    concepts=[('状态统一约束事件',['仅运行时下落和计分','暂停保留位置与分数','结束后重新开始才能恢复'],'让学生把StartButton在三种可用状态下的作用说清。结束时按钮禁用，ResetButton仍是可达入口。'),('规则集中，先后明确',['漏接先扣生命，再判断','加分后重新计算难度','结束关闭Clock并保存结果'],'若先判断再扣命，会多活一轮；若结束不停止Timer，可能继续扣成负数。先用一命边界演算再看完整过程。')],
    tasks=[task('漏接先扣生命',['在FallClock.Timer的漏接分支，把生命设为生命-1。','若生命≤0调用结束游戏，否则更新面板并重置苹果。','测试三次漏接，检查3→2→1→0，结束后不继续扣。'],'为什么必须先扣生命再检查是否≤0？','判断的是这次漏接之后的剩余生命；先检查会用旧值，可能多允许一次。'),task('完成递增难度',['找到调整难度占位过程。','设置下落步长=min(12,5+floor(得分/5))。','手算4、5、10、35、40分，再核对接物后的变化。'],'为什么floor(得分/5)而不是直接得分/5？','本规则按完整5分一档，floor取已完成档数；否则每加1分都会出现小数加速。'),task('结束和重新开始分开',['结束游戏设置状态结束、Clock关闭、苹果隐藏、开始按钮禁用并显示最终分数。','检查已给的重新开始过程恢复0分3命步长5、待开始与按钮可用。','暂停后继续确认位置不重置；结束后重开确认全状态恢复。'],'为什么继续不能直接调用重新开始？','继续应保留分数、生命和苹果位置；重新开始会清掉本局进度。')],
    tests=[test('连续漏接三次','生命3→2→1→0，状态结束，Clock关闭。'),test('4分接到一个苹果','得分5，步长从5变6。'),test('达到35分再继续加分','步长12并封顶。'),test('苹果在Y120暂停再继续','保持原位置继续，不回到顶部。'),test('结束后点重新开始','0分、3生命、步长5、待开始，开始键重新可用。')],
    blocks=[('漏接分支先扣命再判断',['只在运行状态处理','扣生命后检查≤0','未结束才重置苹果'],'对照第19课只重生的分支。本课新增的状态保护与结束调用是重点，不能省掉Timer入口条件。'),('每5分提升一档',['floor(得分÷5)计算档位','基础步长5加档位','min限制最大12'],'手算4分得0档、5分1档、35分7档。间隔仍30ms，提升的是每次下落距离。'),('结束游戏保留最终结果',['状态结束并停止Clock','隐藏苹果、禁用开始','说明最终分并留下重开入口'],'结束过程不归零，最终得分应保留给用户看。归零由重新开始负责，这两种过程不能混为一个。')],
    trace=[['得分/操作','状态或计算','结果'],['4分','5+floor(4/5)','步长5'],['5分','5+floor(5/5)','步长6'],['35分','min(12,12)','步长12'],['40分','min(12,13)','仍12'],['1命漏接','1-1=0','结束']],
    pitfalls=[['生命变成负数','Timer检查运行态，结束时关闭Clock。'],['暂停后继续分数归零','继续不能调用重新开始。'],['结束后看不到最终成绩','结束过程不应清得分。'],['速度无限增加','难度公式保留min(12,…)上限。']],
    challenges=['完成扣命、难度和结束，保留第19课基础行为。','调整每档所需分数，并先重新编写边界测试。','增加一条可解释的新规则，如特殊苹果；先规定与暂停、结束状态的关系。'],
    exits=[question('5分时步长是多少？35分呢？','6和12。'),question('生命1时漏接，先做什么再判断什么？','先扣到0，再判断≤0并结束。'),question('结束游戏与重新开始为什么要分开？','前者保留最终结果并停止，后者才恢复初始数据与操作入口。')],
    remix='把每5分加速改为每10分，先列9、10、20分的预期再修改公式。',
